/**
 * @file    WebUI.h
 * @brief   Embedded web interface assets stored as PROGMEM string literals.
 * @details Contains all HTML/CSS/JavaScript for the web interface as raw string
 * literals in PROGMEM. Compressed versions (gzip) are generated by
 * compressor.py and stored in WebUI_GZ.h for bandwidth-efficient
 * delivery to clients that support Accept-Encoding: gzip.
 *
 * @project SIMUT — Sistema Integrado de Monitoramento Universal de Temperatura
 * @target  Raspberry Pi Pico W (RP2040) — Arduino Framework
 * @license MIT License
 */

